import{B,C,read,diagramStage,path}from'../ten-utils.js';
export default({g,p,extra,t})=>{let m=extra.mode??0,k=p[0];if(m===0){let pts=[[-1.3,.6,0],[-.65,-.1,0],[0,-.6,0],[.65,-.1,0],[1.3,.6,0]],names=[B('Receptor','ग्राही'),B('Sensory neuron','संवेदी न्यूरॉन'),B('Spinal cord relay','मेरुरज्जु में संपर्क'),B('Motor neuron','प्रेरक न्यूरॉन'),B('Effector muscle','प्रभावक पेशी')];diagramStage(g,pts,k,t,names);return[read('Reflex arc stage','प्रतिवर्ती चाप की अवस्था',names[k]),read('Direction','दिशा',B('Receptor → sensory neuron → spinal cord → motor neuron → muscle','ग्राही → संवेदी न्यूरॉन → मेरुरज्जु → प्रेरक न्यूरॉन → पेशी'))]}
if(m===1){let pts=Array.from({length:15},(_,i)=>[Math.pow(i/14,2)*k*.07,.9-i*.12,0]);path(g,pts,C.green,5);g.sphere(...pts.at(-1),.15,C.green,B('Shoot tip','प्ररोह का सिरा'));g.sphere(1.2,-.8,0,.2,C.gold,B('Light','प्रकाश'));g.arrow([1,-.7,0],[.4,-.6,0],C.gold);return[read('Model time','मॉडल समय',k,'hours'),read('Growth response','वृद्धि अनुक्रिया',B('Auxin promotes greater cell elongation on the shaded side of the shoot','ऑक्सिन प्ररोह के छायादार भाग की कोशिकाओं में अधिक लंबाई-वृद्धि कराता है'))]}
g.box(0,0,0,.65,.3,.2,C.pink);g.text(0,-.65,0,B('Pancreas → insulin → glucose regulation','अग्न्याशय → इंसुलिन → ग्लूकोज़ नियंत्रण'));for(let i=0;i<k/5;i++)g.sphere(-1.2+(i%7)*.36,.6+Math.floor(i/7)*.2,0,.06,C.gold);return[read('Glucose input','ग्लूकोज़ निवेश',k,'relative units'),read('Feedback','पुनर्भरण',k>50?B('Increased glucose stimulates insulin secretion in this simplified feedback','सरल मॉडल में अधिक ग्लूकोज़ इंसुलिन स्रवण को प्रेरित करता है'):B('Insulin demand is lower in this qualitative model','इस गुणात्मक मॉडल में इंसुलिन की आवश्यकता कम है'))]};
